1	#!/usr/bin/env node
2	/**
3	 * doctrine60-probe.mjs — FROZEN counter for kumitate round 60, claim C2 (rule D60).
4	 *
5	 *   node .ufo/waves/round-60/probe/doctrine60-probe.mjs <lane> <rev>
6	 *
7	 * Predicate DOCTRINE60_HELD, byte-identical with plan.md §Claims and the report:
8	 * DOCTRINE60_HELD — node .ufo/waves/round-60/probe/doctrine60-probe.mjs /home/vgpnk/Projects/shokunin/kumitate-shokunin <rev> prints "DOCTRINE60: DOCTRINE60_HELD held=6/6 checks=6 rev=<rev> rule=D60" and exits 0.
9	 *
10	 * Six checks over the committed bytes of <rev> (git archive, never the worktree):
11	 *   F1  both adopted entries exist; each head carries verified-at: 2026-10-24 and recheck:;
12	 *       each first line cites its own ids and URLs.
13	 *   F2  the seven rows exist in corpus/SOURCES.md: 11 cells, status mined, opened 2026-10-24,
14	 *       no literal or escaped pipe in any cell, recheck cell an ISO date, NNd or a symbolic cadence.
15	 *   F3  each row's used-by names exactly the admitted entry that cites it, and that path exists.
16	 *   F4  .ufo/pins/source-captures.json pins all seven and each capture blob's sha256 matches its pin.
17	 *   F5  .ufo/pins/source-dupes.json pins the S117/S126 group and source-dupes at rev reads CLEAN.
18	 *   F6  the lesson's ## Gate records the two ADMITs and the two REJECTs with flips, and the
19	 *       collisions file names exactly S125/S127/S136 and none of the seven adopted ids.
20	 *
21	 * Frozen before any data seat scored.
22	 */
23	import { spawnSync } from 'node:child_process';
24	import { createHash } from 'node:crypto';
25	import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
26	import { tmpdir } from 'node:os';
27	import { join, resolve } from 'node:path';
28	
29	const RULE = 'D60';
30	const EXPECTED_CHECKS = 6;
31	const IDS = ['S126', 'S131', 'S133', 'S134', 'S135', 'S190', 'S194'];
32	const ENTRY_FANOUT = 'corpus/knowledge/durable-execution-and-fanout-primitives-2026-10-24.md';
33	const ENTRY_DETECT = 'corpus/knowledge/durable-execution-failure-detection.md';
34	const CADENCE = /^(\d{4}-\d{2}-\d{2}|\d+d|on-release|on-release\b|quarterly|monthly|weekly|yearly)$/i;
35	
36	const [laneArg, rev, ...rest] = process.argv.slice(2);
37	if (!laneArg || !rev || rest.length) {
38	  process.stderr.write('DOCTRINE60: USAGE node doctrine60-probe.mjs <lane> <rev>\n');
39	  process.exit(64);
40	}
41	const lane = resolve(laneArg);
42	if (!existsSync(join(lane, '.git'))) {
43	  process.stderr.write(`DOCTRINE60: USAGE ${JSON.stringify(lane)} is not a git repo\n`);
44	  process.exit(64);
45	}
46	if (!/^[0-9a-f]{7,64}$/.test(rev)) {
47	  process.stderr.write('DOCTRINE60: USAGE <rev> must be a lowercase hex object name\n');
48	  process.exit(64);
49	}
50	const sha = (b) => createHash('sha256').update(b).digest('hex');
51	const checks = [];
52	const hold = (id, ok, detail) => checks.push({ id, ok, detail });
53	const T = mkdtempSync(join(tmpdir(), 'd60-probe.'));
54	
55	function finish(code, line) {
56	  rmSync(T, { recursive: true, force: true });
57	  process.stdout.write(line + '\n');
58	  for (const c of checks) process.stdout.write(` | ${c.id} ${c.ok ? 'PASS' : 'MISS'} ${c.detail}`);
59	  if (checks.length) process.stdout.write('\n');
60	  process.exit(code);
61	}
62	
63	try {
64	  const tar = spawnSync('bash', ['-lc',
65	    `git -C ${JSON.stringify(lane)} archive ${JSON.stringify(rev)} | tar -x -C ${JSON.stringify(T)}`],
66	    { encoding: 'utf8', timeout: 180000 });
67	  if (tar.status !== 0) {
68	    process.stderr.write(`DOCTRINE60: FAIL-CLOSED rev unreadable (${tar.status})\n`);
69	    rmSync(T, { recursive: true, force: true });
70	    process.exit(2);
71	  }
72	  const readT = (p) => { try { return readFileSync(join(T, p)); } catch { return null; } };
73	  const text = (p) => { const b = readT(p); return b ? b.toString('utf8') : null; };
74	
75	  {
76	    const a = text(ENTRY_FANOUT);
77	    const b = text(ENTRY_DETECT);
78	    const headOk = (s) => {
79	      if (!s) return false;
80	      const head = s.split('\n').slice(0, 6).join('\n');
81	      return /verified-at:\s*2026-10-24/.test(head) && /recheck:/.test(head);
82	    };
83	    const firstOk = (s, ids) => {
84	      if (!s) return false;
85	      const first = s.split('\n')[0] || '';
86	      return ids.every((i) => first.includes(i));
87	    };
88	    const ok = headOk(a) && headOk(b)
89	      && firstOk(a, ['S190', 'S194']) && firstOk(b, ['S126', 'S131', 'S133', 'S134', 'S135'])
90	      && /research\.google\.com|research\.google/.test(a.split('\n')[0] || '')
91	      && /dl\.acm\.org/.test(a.split('\n')[0] || '')
92	      && /docs\.temporal\.io/.test(b.split('\n')[0] || '');
93	    hold('F1', ok, `fanout=${!!a} detect=${!!b}`);
94	  }
95	  {
96	    const sources = text('corpus/SOURCES.md') || '';
97	    const why = [];
98	    for (const id of IDS) {
99	      const row = sources.split('\n').find((l) => new RegExp(`^ {0,3}\\|\\s*${id}\\s*\\|`).test(l));
100	      if (!row) { why.push(`${id}:missing`); continue; }
101	      const cells = row.split('|').slice(1, -1).map((c) => c.trim());
102	      if (cells.length !== 11) why.push(`${id}:cols=${cells.length}`);
103	      if (cells[7] !== 'mined') why.push(`${id}:status`);
104	      if (cells[8] !== '2026-10-24') why.push(`${id}:opened`);
105	      if (!CADENCE.test(cells[9] || '')) why.push(`${id}:recheck=${cells[9]}`);
106	      if (row.includes('\\|')) why.push(`${id}:escaped-pipe`);
107	      for (const c of cells) if (c.includes('|')) why.push(`${id}:literal-pipe`);
108	    }
109	    hold('F2', why.length === 0, why.length ? why.join(',') : `rows=${IDS.length}`);
110	  }
111	  {
112	    const sources = text('corpus/SOURCES.md') || '';
113	    const owner = {};
114	    owner.S190 = ENTRY_FANOUT; owner.S194 = ENTRY_FANOUT;
115	    owner.S126 = ENTRY_DETECT; owner.S131 = ENTRY_DETECT; owner.S133 = ENTRY_DETECT;
116	    owner.S134 = ENTRY_DETECT; owner.S135 = ENTRY_DETECT;
117	    const why = [];
118	    for (const id of IDS) {
119	      const row = sources.split('\n').find((l) => new RegExp(`^ {0,3}\\|\\s*${id}\\s*\\|`).test(l));
120	      if (!row) { why.push(`${id}:missing`); continue; }
121	      const cells = row.split('|').slice(1, -1).map((c) => c.trim());
122	      const usedBy = (cells[10] || '').split(',').map((s) => s.trim()).filter(Boolean);
123	      if (usedBy.length !== 1 || usedBy[0] !== owner[id]) { why.push(`${id}:used-by=${usedBy.join('+')}`); continue; }
124	      if (!readT(owner[id])) why.push(`${id}:path-absent`);
125	    }
126	    hold('F3', why.length === 0, why.length ? why.join(',') : 'used-by-exact');
127	  }
128	  {
129	    const pins = text('.ufo/pins/source-captures.json');
130	    let doc = null;
131	    try { doc = pins ? JSON.parse(pins) : null; } catch { doc = null; }
132	    const captures = doc && Array.isArray(doc.captures) ? doc.captures : [];
133	    const why = [];
134	    for (const id of IDS) {
135	      const pin = captures.find((c) => c.sourceId === id);
136	      if (!pin) { why.push(`${id}:unpin`); continue; }
137	      const blob = readT(pin.path);
138	      if (!blob) { why.push(`${id}:capture-absent`); continue; }
139	      if (sha(blob) !== pin.sha256) why.push(`${id}:hash-miss`);
140	      if (String(pin.bytes) !== String(blob.length)) why.push(`${id}:bytes-miss`);
141	    }
142	    hold('F4', why.length === 0, why.length ? why.join(',') : `captures=${IDS.length}`);
143	  }
144	  {
145	    const pins = text('.ufo/pins/source-dupes.json');
146	    let doc = null;
147	    try { doc = pins ? JSON.parse(pins) : null; } catch { doc = null; }
148	    const known = doc && Array.isArray(doc.known) ? doc.known : [];
149	    const group = known.find((g) => Array.isArray(g.ids) && g.ids.includes('S117') && g.ids.includes('S126'));
150	    const run = spawnSync('node', [join(T, 'scripts/source-dupes.mjs'),
151	      '--registry', '.ufo/pins/source-dupes.json', '--sources', 'corpus/SOURCES.md'],
152	      { cwd: T, encoding: 'utf8', timeout: 120000 });
153	    const out = `${run.stdout || ''}${run.stderr || ''}`;
154	    const ok = !!group && run.status === 0 && /SOURCE_DUPES: CLEAN/.test(out);
155	    hold('F5', ok, `group=${!!group} exit=${run.status} ${out.split('\n')[0] || ''}`);
156	  }
157	  {
158	    const lesson = text('corpus/lessons/round-60.md') || '';
159	    const a1 = lesson.includes('ADMIT durable-execution-and-fanout-primitives-2026-10-24.md');
160	    const a2 = lesson.includes('ADMIT durable-execution-failure-detection.md');
161	    const r1 = lesson.includes('REJECT exactly-once-attribution.md');
162	    const r2 = lesson.includes('REJECT multi-agent-coordinator-topologies.md');
163	    const flips = (lesson.match(/flip:/g) || []).length;
164	    const col = text('.ufo/waves/round-60/assimilation/collisions');
165	    const colIds = (col || '').split('\n').map((s) => s.trim()).filter(Boolean);
166	    const colOk = colIds.length === 3 && ['S125', 'S127', 'S136'].every((i) => colIds.includes(i))
167	      && !colIds.some((i) => IDS.includes(i));
168	    const ok = a1 && a2 && r1 && r2 && flips >= 2 && colOk;
169	    hold('F6', ok, `admit=${a1 && a2} reject=${r1 && r2} flips=${flips} collisions=${colIds.join('+') || 'none'}`);
170	  }
171	} catch (err) {
172	  process.stderr.write(`DOCTRINE60: FAIL-CLOSED ${err && err.message}\n`);
173	  rmSync(T, { recursive: true, force: true });
174	  process.exit(2);
175	}
176	
177	const held = checks.filter((c) => c.ok).length;
178	const mismatch = checks.length !== EXPECTED_CHECKS;
179	const head = `DOCTRINE60: ${mismatch ? 'DOCTRINE60_UNMET' : (held === EXPECTED_CHECKS ? 'DOCTRINE60_HELD' : 'DOCTRINE60_UNMET')} held=${held}/${checks.length} checks=${EXPECTED_CHECKS} rev=${rev} rule=${RULE}${mismatch ? ' checks-mismatch' : ''}`;
180	finish(held === EXPECTED_CHECKS && !mismatch ? 0 : 1, head);
